dtsPropsFor.Medal:
/** Ribbon colourway. @default "blue" */
  ribbon?: "blue" | "red" | "green" | "gold" | "tricolor";
  /** Single character struck on the disk. @default "L" */
  letter?: string;
  /** Native tooltip text — the award's full name. */
  title?: string;

dtsPropsFor.Crest:
/** Rendered width and height in px. @default 40 */
  size?: number;
  /** Override the regiment mark. Defaults to the inlined crest data URI. */
  src?: string;

dtsPropsFor.Avatar:
/** Full name; initials and a deterministic oklch hue are derived from it. @default "??" */
  name?: string;
  /** Diameter in px; the font scales with it. @default 32 */
  size?: number;
  /** Show the green Discord presence dot. */
  online?: boolean;

dtsPropsFor.Sidebar:
/** Id of the active nav item. @default "home" */
  active?: "home" | "events" | "gallery" | "roster" | "apps" | "ranks" | "audit" | "settings" | "profile";
  /** Fired with the item id when a nav row is clicked. */
  onNav?: (id: string) => void;
  /** Signed-in member shown in the sidebar footer. */
  user?: { name?: string; rank?: string };
  /** Render the "Command" (admin) nav group. @default true */
  isAdmin?: boolean;

dtsPropsFor.Topbar:
/** Breadcrumb trail; the last entry is styled as the current page. @default [] */
  crumbs?: string[];
  /** Extra controls rendered after the notices bell. */
  actions?: React.ReactNode;
  /** Show the roster/events search field. @default true */
  search?: boolean;

dtsPropsFor.PageHead:
/** Page title, set in the display serif. */
  title?: React.ReactNode;
  /** Supporting line under the title. */
  sub?: React.ReactNode;
  /** Buttons aligned to the right of the heading. */
  actions?: React.ReactNode;
  /** Brass uppercase kicker above the title. */
  eyebrow?: React.ReactNode;

dtsPropsFor.SectionHead:
/** Section label, followed by a hairline rule. */
  title?: React.ReactNode;
  /** Content pinned to the right of the rule. */
  right?: React.ReactNode;

dtsPropsFor.AppShell:
/** Id of the active sidebar item. */
  active?: "home" | "events" | "gallery" | "roster" | "apps" | "ranks" | "audit" | "settings" | "profile";
  /** Fired with the item id when a nav row is clicked. */
  onNav?: (id: string) => void;
  /** Breadcrumb trail passed through to the Topbar. */
  crumbs?: string[];
  /** Page content, rendered in the scrolling area. */
  children?: React.ReactNode;
  /** Extra Topbar controls. */
  topActions?: React.ReactNode;
  /** Signed-in member shown in the sidebar footer. */
  user?: { name?: string; rank?: string };

dtsPropsFor.DiscordBtn:
/** Button label. @default "Continue with Discord" */
  children?: React.ReactNode;
  /** Pass "lg" for the tall variant used on sign-in screens. */
  size?: "lg";

dtsPropsFor.RankPip:
/** Rank name shown beside the chevrons. @default "Lieutenant" */
  name?: string;
  /** Number of chevrons. @default 2 */
  n?: number;

dtsPropsFor.StatTile:
/** Uppercase label above the figure. */
  label?: React.ReactNode;
  /** The figure itself, set in the display serif. */
  value?: React.ReactNode;
  /** Small caption under the figure. */
  foot?: React.ReactNode;
  /** CSS colour for the figure. @default "var(--t-100)" */
  accent?: string;
